-- V112 — Aria v2: workflow reachability compliance
-- The workflow-compliance audit found 9 of 48 active workflows non-compliant:
-- 7 had a terminal state (CANCELLED/EXPIRED/DESTROYED) that NO transition entered
-- (a dead state); 2 were empty stubs (initialState but no states/transitions).
-- Adds cancel/expire transitions into the orphan terminals from every active state
-- (trigger workflow.transition, or system.schedule for EXPIRED — both page-less),
-- and installs a minimal valid state machine for the 2 stubs. Idempotent.
-- Pure substrate data; no @Entity or business table touched.

-- M5.SalesOrder: +6 transition(s) into ['CANCELLED']
UPDATE workflow_definition SET body_json='{"code":"M5.SalesOrder","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT","assignedRole":"Dispatch"},{"code":"CONFIRMED","assignedRole":"UnloadingSupervisor"},{"code":"IN_PRODUCTION","assignedRole":"UnloadingSupervisor"},{"code":"READY_TO_DISPATCH","assignedRole":"Dispatch"},{"code":"DISPATCHED","assignedRole":"Dispatch"},{"code":"INVOICED","assignedRole":"Dispatch"},{"code":"CLOSED","terminal":true},{"code":"CANCELLED","terminal":true}],"transitions":[{"from":"DRAFT","to":"CONFIRMED","trigger":"page.submitted","pageCode":"pico:so-confirm"},{"from":"CONFIRMED","to":"IN_PRODUCTION","trigger":"page.submitted","pageCode":"pico:so-production"},{"from":"IN_PRODUCTION","to":"READY_TO_DISPATCH","trigger":"page.submitted","pageCode":"pico:so-ready"},{"from":"READY_TO_DISPATCH","to":"DISPATCHED","trigger":"page.submitted","pageCode":"pico:so-dispatch"},{"from":"DISPATCHED","to":"INVOICED","trigger":"page.submitted","pageCode":"pico:so-invoice"},{"from":"INVOICED","to":"CLOSED","trigger":"page.submitted","pageCode":"pico:so-close"},{"from":"DISPATCHED","to":"CANCELLED","trigger":"workflow.transition"},{"from":"READY_TO_DISPATCH","to":"CANCELLED","trigger":"workflow.transition"},{"from":"IN_PRODUCTION","to":"CANCELLED","trigger":"workflow.transition"},{"from":"DRAFT","to":"CANCELLED","trigger":"workflow.transition"},{"from":"CONFIRMED","to":"CANCELLED","trigger":"workflow.transition"},{"from":"INVOICED","to":"CANCELLED","trigger":"workflow.transition"}]}' WHERE code='M5.SalesOrder' AND version=1;
-- M6.SalesInvoice: +5 transition(s) into ['CANCELLED']
UPDATE workflow_definition SET body_json='{"code":"M6.SalesInvoice","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT","assignedRole":"Dispatch"},{"code":"FINALIZED","assignedRole":"Manager"},{"code":"E_INVOICED","assignedRole":"Dispatch"},{"code":"SENT","assignedRole":"Dispatch"},{"code":"PARTIAL","assignedRole":"Dispatch"},{"code":"PAID","terminal":true},{"code":"CANCELLED","terminal":true}],"transitions":[{"from":"DRAFT","to":"FINALIZED","trigger":"page.submitted","pageCode":"pico:si-finalize"},{"from":"FINALIZED","to":"E_INVOICED","trigger":"page.submitted","pageCode":"pico:si-einvoice"},{"from":"E_INVOICED","to":"SENT","trigger":"page.submitted","pageCode":"pico:si-send"},{"from":"SENT","to":"PARTIAL","trigger":"page.submitted","pageCode":"pico:si-payment","guard":"#submitted[''mode''] == ''PARTIAL''"},{"from":"SENT","to":"PAID","trigger":"page.submitted","pageCode":"pico:si-payment","guard":"#submitted[''mode''] == ''FULL''"},{"from":"PARTIAL","to":"PAID","trigger":"page.submitted","pageCode":"pico:si-payment","guard":"#submitted[''mode''] == ''FULL''"},{"from":"DRAFT","to":"CANCELLED","trigger":"workflow.transition"},{"from":"FINALIZED","to":"CANCELLED","trigger":"workflow.transition"},{"from":"PARTIAL","to":"CANCELLED","trigger":"workflow.transition"},{"from":"SENT","to":"CANCELLED","trigger":"workflow.transition"},{"from":"E_INVOICED","to":"CANCELLED","trigger":"workflow.transition"}]}' WHERE code='M6.SalesInvoice' AND version=1;
-- M5.Subscription: +2 transition(s) into ['EXPIRED']
UPDATE workflow_definition SET body_json='{"code":"M5.Subscription","version":1,"initialState":"ACTIVE","states":[{"code":"ACTIVE","assignedRole":"Dispatch"},{"code":"PAUSED","assignedRole":"Manager"},{"code":"CANCELLED","terminal":true},{"code":"EXPIRED","terminal":true}],"transitions":[{"from":"ACTIVE","to":"PAUSED","trigger":"page.submitted","pageCode":"pico:sub-pause"},{"from":"PAUSED","to":"ACTIVE","trigger":"page.submitted","pageCode":"pico:sub-resume"},{"from":"ACTIVE","to":"CANCELLED","trigger":"page.submitted","pageCode":"pico:sub-cancel"},{"from":"PAUSED","to":"CANCELLED","trigger":"page.submitted","pageCode":"pico:sub-cancel"},{"from":"ACTIVE","to":"EXPIRED","trigger":"system.schedule"},{"from":"PAUSED","to":"EXPIRED","trigger":"system.schedule"}]}' WHERE code='M5.Subscription' AND version=1;
