UPDATE workflow_definition SET body_json='{"code":"M5.AmcContract","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT","assignedRole":"Dispatch"},{"code":"ACTIVE","assignedRole":"Dispatch"},{"code":"PM_DUE","assignedRole":"UnloadingSupervisor"},{"code":"EXPIRED","terminal":true},{"code":"TERMINATED","terminal":true}],"transitions":[{"from":"DRAFT","to":"ACTIVE","trigger":"page.submitted","pageCode":"pico:amc-activate"},{"from":"ACTIVE","to":"PM_DUE","trigger":"page.submitted","pageCode":"pico:amc-pm-trigger"},{"from":"PM_DUE","to":"ACTIVE","trigger":"page.submitted","pageCode":"pico:amc-pm-done"},{"from":"ACTIVE","to":"TERMINATED","trigger":"page.submitted","pageCode":"pico:amc-terminate"},{"from":"ACTIVE","to":"EXPIRED","trigger":"system.schedule"},{"from":"PM_DUE","to":"EXPIRED","trigger":"system.schedule"},{"from":"DRAFT","to":"EXPIRED","trigger":"system.schedule"}]}' WHERE code='M5.AmcContract' AND version=1;
-- M8.Quote: +2 transition(s) into ['EXPIRED']
UPDATE workflow_definition SET body_json='{"code":"M8.Quote","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT","assignedRole":"Dispatch"},{"code":"SENT","assignedRole":"Manager"},{"code":"ACCEPTED","terminal":true},{"code":"REJECTED","terminal":true},{"code":"EXPIRED","terminal":true}],"transitions":[{"from":"DRAFT","to":"SENT","trigger":"page.submitted","pageCode":"pico:quote-send"},{"from":"SENT","to":"ACCEPTED","trigger":"page.submitted","pageCode":"pico:quote-outcome","guard":"#submitted[''outcome''] == ''ACCEPTED''"},{"from":"SENT","to":"REJECTED","trigger":"page.submitted","pageCode":"pico:quote-outcome","guard":"#submitted[''outcome''] == ''REJECTED''"},{"from":"SENT","to":"EXPIRED","trigger":"system.schedule"},{"from":"DRAFT","to":"EXPIRED","trigger":"system.schedule"}]}' WHERE code='M8.Quote' AND version=1;
